BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='1s';
WITH activity AS (
 SELECT count(*) AS connections,
 count(*) FILTER(WHERE state='active') AS active,
 count(*) FILTER(WHERE wait_event_type='Lock') AS waiting_lock,
 count(*) FILTER(WHERE state='idle in transaction') AS idle_in_transaction,
 current_setting('max_connections') AS max_connections
 FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid()
), relations AS (
 SELECT c.relname AS name,c.reltuples AS estimated_rows
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind='r'
 AND (c.relname IN ('mercadona_products','carrefour_products','consum_products','plusfresc_products')
 OR c.relname LIKE 'catalog%location%' OR c.relname LIKE 'catalog%sync%')
), columns AS (
 SELECT table_name,column_name,data_type
 FROM information_schema.columns
 WHERE table_schema='public'
 AND (table_name LIKE 'catalog%location%' OR table_name LIKE 'catalog%sync%')
)
SELECT jsonb_build_object('captured_at',now(),'activity',(SELECT to_jsonb(a) FROM activity a),
 'relations',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.name) FROM relations r),
 'columns',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.table_name,c.column_name) FROM columns c)) AS evidence;
ROLLBACK;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
SELECT jsonb_build_object(
 'captured_at',now(),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) ORDER BY indexname) FROM pg_indexes WHERE schemaname='public' AND tablename='catalog_location_prices'),
 'syncs',(SELECT jsonb_agg(to_jsonb(s) ORDER BY s.store) FROM public.catalog_sync_status s WHERE store IN ('mercadona','carrefour','consum','plusfresc')),
 'locations',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.store,t.location_id) FROM (SELECT store,location_id FROM public.catalog_location_prices GROUP BY store,location_id ORDER BY store,location_id LIMIT 41) t)
) AS evidence;
ROLLBACK;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s';
WITH targets(store,location_id) AS (
 VALUES ('consum'::text,'575'::text),('plusfresc','3'),('plusfresc','12')
), samples AS (
 SELECT t.store,t.location_id,p.product_id,p.unit_price,p.available,p.synced_at
 FROM targets t CROSS JOIN LATERAL (
  SELECT product_id,unit_price,available,synced_at
  FROM public.catalog_location_prices p
  WHERE p.store=t.store AND p.location_id=t.location_id AND p.published
  ORDER BY product_id LIMIT 200
 ) p
), measures AS (
 SELECT store,location_id,count(*) AS sample_size,
 count(*) FILTER (WHERE unit_price>0) AS positive_price,
 count(*) FILTER (WHERE available) AS available_flag,
 min(synced_at) AS min_synced_at,max(synced_at) AS max_synced_at
 FROM samples GROUP BY store,location_id
)
SELECT jsonb_build_object('captured_at',now(),
 'sample_method','First 200 published rows by product_id per selected store/location, not random or family-stratified',
 'samples',(SELECT jsonb_agg(to_jsonb(m) ORDER BY m.store,m.location_id) FROM measures m),
 'activity',(SELECT jsonb_build_object('connections',count(*),'active',count(*) FILTER(WHERE state='active'),'waiting_lock',count(*) FILTER(WHERE wait_event_type='Lock'),'idle_in_transaction',count(*) FILTER(WHERE state='idle in transaction')) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid())
) AS evidence; ROLLBACK;
